<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Oidc\Common\Application\Usecase;

use Civi\Lughauth\Shared\Context;
use Civi\Lughauth\Shared\Value\Random;
use Civi\Lughauth\Shared\Security\AesCypherService;
use Civi\Lughauth\Shared\Infrastructure\Sql\SqlTemplate;
use Civi\Lughauth\Features\Access\RelyingParty\Domain\Gateway\RelyingPartyWriteGateway;
use Civi\Lughauth\Features\Access\RelyingParty\Domain\RelyingParty;
use Civi\Lughauth\Features\Access\RelyingParty\Domain\RelyingPartyAttributes;
use Civi\Lughauth\Features\Access\Role\Domain\Gateway\RoleWriteGateway;
use Civi\Lughauth\Features\Access\Role\Domain\Role;
use Civi\Lughauth\Features\Access\Role\Domain\RoleAttributes;
use Civi\Lughauth\Features\Access\Role\Domain\RoleRef;
use Civi\Lughauth\Features\Access\Tenant\Domain\Gateway\TenantWriteGateway;
use Civi\Lughauth\Features\Access\Tenant\Domain\Tenant;
use Civi\Lughauth\Features\Access\Tenant\Domain\TenantAttributes;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\Gateway\TrustedClientWriteGateway;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\TrustedClient;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\TrustedClientAttributes;
use Civi\Lughauth\Features\Access\User\Domain\Gateway\UserWriteGateway;
use Civi\Lughauth\Features\Access\User\Domain\User;
use Civi\Lughauth\Features\Access\User\Domain\UserAttributes;
use Civi\Lughauth\Features\Access\User\Domain\UserRef;
use Civi\Lughauth\Features\Access\User\Domain\ValueObject\UserPasswordVO;
use Civi\Lughauth\Features\Access\ApiKeyClient\Domain\ApiKeyClient;
use Civi\Lughauth\Features\Access\ApiKeyClient\Domain\ApiKeyClientAttributes;
use Civi\Lughauth\Features\Access\ApiKeyClient\Domain\Gateway\ApiKeyClientWriteGateway;
use Civi\Lughauth\Features\Access\UserRoleAssignament\Domain\Gateway\UserRoleAssignamentWriteGateway;
use Civi\Lughauth\Features\Access\UserRoleAssignament\Domain\UserRoleAssignament;
use Civi\Lughauth\Features\Access\UserRoleAssignament\Domain\UserRoleAssignamentAttributes;
use Civi\Lughauth\Features\Access\UserRoleAssignament\Domain\ValueObject\UserRoleAssignamentRolesItem;
use Civi\Lughauth\Features\Access\UserRoleAssignament\Domain\ValueObject\UserRoleAssignamentRolesListRef;
use Civi\Lughauth\Features\Access\UserRoleAssignament\Domain\ValueObject\UserRoleAssignamentRolesRoleVO;
use Civi\Lughauth\Features\Access\UserRoleAssignament\Domain\ValueObject\UserRoleAssignamentRolesUidVO;
use Civi\Lughauth\Features\Access\UserRoleAssignament\Domain\ValueObject\UserRoleAssignamentRolesVersionVO;
use Civi\Lughauth\Features\Access\UserGroupMembership\Domain\Gateway\UserGroupMembershipWriteGateway;
use Civi\Lughauth\Features\Access\UserGroupMembership\Domain\UserGroupMembership;
use Civi\Lughauth\Features\Access\UserGroupMembership\Domain\UserGroupMembershipAttributes;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\TrustedClientAllowedRedirectsItem;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\TrustedClientAllowedRedirectsUidVO;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\TrustedClientAllowedRedirectsUrlVO;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\TrustedClientAllowedRedirectsVersionVO;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\TrustedClientSecretOauthVO;
use Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Domain\Gateway\SmtpOutboundConfigWriteGateway;
use Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Domain\SmtpOutboundConfig;
use Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Domain\SmtpOutboundConfigAttributes;
use Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Domain\ValueObject\SmtpOutboundConfigPasswordVO;
use Civi\Lughauth\Features\Oidc\Common\Application\Usecase\Install\InstallLoginTemplate;
use Civi\Lughauth\Features\Oidc\Common\Application\Usecase\Install\InstallPasswordRecoverTemplate;
use Civi\Lughauth\Features\Oidc\Common\Application\Usecase\Install\InstallUserRegisterTemplate;
use Civi\Lughauth\Features\Oidc\Common\Application\Usecase\Install\InstallAskForDeleteTemplate;
use Civi\Lughauth\Features\Oidc\Common\Application\Usecase\Install\InstallSendMagicLinkTemplate;
use Civi\Lughauth\Features\Oidc\Common\Application\Usecase\Install\InstallDelegateLoginTemplate;
use Civi\Lughauth\Features\Oidc\Common\Application\Usecase\Install\InstallIndexPageTemplate;
use Civi\Lughauth\Features\Oidc\Common\Application\Usecase\Install\InstallFullPageTemplate;
use Civi\Lughauth\Features\Oidc\Common\Application\Usecase\Install\InstallInvitationTemplate;
use Civi\Lughauth\Features\Oidc\Common\Application\Usecase\Install\InstallCorporateTheme;

class InstallUsecase
{
    public function __construct(
        private readonly Context $context,
        private readonly SqlTemplate $template,
        private readonly AesCypherService $cypher,
        private readonly RelyingPartyWriteGateway $createReling,
        private readonly TrustedClientWriteGateway $createTruted,
        private readonly TenantWriteGateway $createTenant,
        private readonly RoleWriteGateway $createRole,
        private readonly UserWriteGateway $createUser,
        private readonly UserRoleAssignamentWriteGateway $createUserRoleAssignament,
        private readonly UserGroupMembershipWriteGateway $createUserGroupMembership,
        private readonly ApiKeyClientWriteGateway $apiKeys,
        private readonly SmtpOutboundConfigWriteGateway $createSmtp,
        private readonly InstallLoginTemplate $loginTemplate,
        private readonly InstallPasswordRecoverTemplate $recoverTemplate,
        private readonly InstallUserRegisterTemplate $registerTemplate,
        private readonly InstallAskForDeleteTemplate $deleteTemplate,
        private readonly InstallSendMagicLinkTemplate $magicLinkTemplate,
        private readonly InstallDelegateLoginTemplate $delegateLoginTemplate,
        private readonly InstallIndexPageTemplate $indexPageTemplate,
        private readonly InstallFullPageTemplate $fullPageTemplate,
        private readonly InstallInvitationTemplate $invitationTemplate,
        private readonly InstallCorporateTheme $corporateTheme,
    ) {
    }

    public function install(): void
    {
        try {
            $this->template->begin();
            $this->init('sesamo');
            $this->template->commit();
        } finally {
            $this->template->close();
        }
    }

    private function init(string $password): void
    {
        $party = new RelyingPartyAttributes();
        $party->uid(Random::comb());
        $party->apiKey('1111');
        $party->code('lughauth-api');
        $party->enabled(true);
        $created = $this->createReling->create(RelyingParty::create($party));
        $this->createReling->update($created, $created->enable());

        $localhost = new TrustedClientAllowedRedirectsItem(
            uid: TrustedClientAllowedRedirectsUidVO::from(Random::comb()),
            url: TrustedClientAllowedRedirectsUrlVO::from('http://localhost:4200/*'),
            version: TrustedClientAllowedRedirectsVersionVO::from(0)
        );

        $trust = new TrustedClientAttributes();
        $trust->uid(Random::comb());
        $trust->code('lughauth-ui');
        $trust->allowAllScopes(true);
        $trust->secretOauth(TrustedClientSecretOauthVO::fromPlainText($this->cypher, '123456'));
        $trust->publicAllow(true);
        $trust->allowedRedirects([$localhost]);
        $trust->enabled(true);
        $created = $this->createTruted->create(TrustedClient::create($trust));
        $this->createTruted->update($created, $created->enable());

        $admin = new RoleAttributes();
        $admin->uid(Random::comb());
        $admin->name("ADMIN");
        $admin = $this->createRole->create(Role::create($admin));

        $root = new RoleAttributes();
        $root->uid(Random::comb());
        $root->name("ROOT");
        $root = $this->createRole->create(Role::create($root));

        $iam = new RoleAttributes();
        $iam->uid(Random::comb());
        $iam->name("IAM");
        $iam = $this->createRole->create(Role::create($iam));

        $tenant = new TenantAttributes();
        $tenant->uid(Random::comb());
        $tenant->root(true);
        $tenant->name("main");
        $tenant->domain("main");
        $createdTenant = $this->createTenant->create(Tenant::create($tenant));
        $createdTenant = $this->createTenant->update($createdTenant, $createdTenant->enable());

        $user = new UserAttributes();
        $user->uid(Random::comb());
        $user->name("ROOT");
        $user->tenant($createdTenant);
        $user->password(UserPasswordVO::fromPlainText($this->cypher, $password));
        $user->enabled(true);
        $created = $this->createUser->create(User::create($user));
        $this->createUser->update($created, $created->enable());

        $roleAdmin = new UserRoleAssignamentRolesItem(
            uid: UserRoleAssignamentRolesUidVO::from(Random::comb()),
            role: UserRoleAssignamentRolesRoleVO::from(new RoleRef($admin->uid() ?? '')),
            version: UserRoleAssignamentRolesVersionVO::from(0)
        );
        $roleRoot = new UserRoleAssignamentRolesItem(
            uid: UserRoleAssignamentRolesUidVO::from(Random::comb()),
            role: UserRoleAssignamentRolesRoleVO::from(new RoleRef($root->uid() ?? '')),
            version: UserRoleAssignamentRolesVersionVO::from(0)
        );
        $iamAdmin = new UserRoleAssignamentRolesItem(
            uid: UserRoleAssignamentRolesUidVO::from(Random::comb()),
            role: UserRoleAssignamentRolesRoleVO::from(new RoleRef($iam->uid() ?? '')),
            version: UserRoleAssignamentRolesVersionVO::from(0)
        );

        $assignament = new UserRoleAssignamentAttributes();
        $assignament->uid(Random::comb());
        $assignament->user(new UserRef($user->getUid() ?? ''));
        $assignament->roles(new UserRoleAssignamentRolesListRef($roleAdmin, $roleRoot, $iamAdmin));
        $this->createUserRoleAssignament->create(UserRoleAssignament::create($assignament));

        $membership = new UserGroupMembershipAttributes();
        $membership->uid(Random::comb());
        $membership->user(new UserRef($user->getUid() ?? ''));
        $membership->groups('root');
        $this->createUserGroupMembership->create(UserGroupMembership::create($membership));

        $apiKey = new ApiKeyClientAttributes();
        $apiKey->uid(Random::comb());
        $apiKey->code('Initial collector');
        $apiKey->key('hcaik_01jtteh99vbsv4qrj22trvh3wg35g1n4tgkcxzgqv0034y2cby7dceaf43');
        $apiKey->scopes('collect');
        $created = $this->apiKeys->create(ApiKeyClient::create($apiKey));
        $this->apiKeys->update($created, $created->enable());

        $apiKey = new ApiKeyClientAttributes();
        $apiKey->uid(Random::comb());
        $apiKey->code('Initial syn client');
        $apiKey->key('sck_01jtteh99vbsv4qrj22trvh3wg35g2n3tgkcxngqv0034y2cby7dceaf43');
        $apiKey->scopes('sync');
        $created = $this->apiKeys->create(ApiKeyClient::create($apiKey));
        $this->apiKeys->update($created, $created->enable());

        $smtp = new SmtpOutboundConfigAttributes();
        $smtp->uid(Random::comb());
        $smtp->host($_ENV['MAILER_HOST'] ?? 'smtp.example.com');
        $smtp->port(true);
        $smtp->login($_ENV['MAILER_USERNAME'] ?? 'noreply@example.com');
        $smtp->password(SmtpOutboundConfigPasswordVO::fromPlainText($this->cypher, $_ENV['MAILER_PASSWORD'] ?? 'change-me'));
        $smtp->senderName($_ENV['MAILER_FROM_NAME'] ?? 'LughAuth');
        $smtp->senderEmail($_ENV['MAILER_FROM_EMAIL'] ?? 'noreply@example.com');
        $smtp->timeout(30);
        $smtp->useTls(filter_var($_ENV['MAILER_START_TLS'] ?? true, FILTER_VALIDATE_BOOLEAN));
        $smtp->maxRetries(3);
        $smtp->retryDelay(60);
        $smtp->rateLimit(100);
        $this->createSmtp->create(SmtpOutboundConfig::create($smtp));

        $this->corporateTheme->install();
        $this->loginTemplate->install();
        $this->recoverTemplate->install();
        $this->registerTemplate->install();
        $this->deleteTemplate->install();
        $this->magicLinkTemplate->install();
        $this->delegateLoginTemplate->install();
        $this->indexPageTemplate->install();
        $this->fullPageTemplate->install();
        $this->invitationTemplate->install();
    }
}
